<script setup lang="ts">
import {computed,onScopeDispose,ref,shallowRef,watch} from 'vue'
import {ApiError,IdentityChanged,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {typeDeviceUuid} from './type-devices-api'
import {iccidPolicyTransport,prepareIccidPolicy,type IccidPolicy,type IccidPolicyIntent,type IccidPolicyTransport,type IccidMode} from './iccid-information-api'
const props=withDefaults(defineProps<{typeId:string;typeStatus?:string;disabled?:boolean;compact?:boolean;transport?:IccidPolicyTransport}>(),{disabled:false,compact:false,transport:()=>iccidPolicyTransport})
const emit=defineEmits<{locked:[value:boolean];changed:[]}>(),roles=['OWNER','ADMIN','OPERATOR','VIEWER']
const denied=ref(false),readable=computed(()=>!denied.value&&session.ready&&!session.transitioning&&!!session.user?.accountId&&typeDeviceUuid.test(projectId.value)&&typeDeviceUuid.test(props.typeId)&&can('device:read')&&roles.includes(session.user?.projectRole||'')&&roles.includes(currentProject.value?.myRole||'')),writable=computed(()=>readable.value&&can('device:update')&&currentProject.value?.status==='ACTIVE'&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const value=shallowRef<IccidPolicy>(),intent=shallowRef<IccidPolicyIntent>(),observed=shallowRef<IccidPolicy>(),shown=ref(false),busy=ref(false),unknown=ref(false),mode=ref<IccidMode>('DISABLED'),propertyKey=ref(''),choices=shallowRef<readonly string[]>([]),choicesBusy=ref(false),error=ref(''),notice=ref(''),locked=computed(()=>shown.value||busy.value||unknown.value)
let generation=0,choiceGeneration=0,alive=true,controller:AbortController|undefined
function clear(){generation++;choiceGeneration++;controller?.abort();value.value=undefined;intent.value=undefined;observed.value=undefined;shown.value=false;busy.value=false;unknown.value=false;choices.value=[];choicesBusy.value=false;propertyKey.value='';error.value='';notice.value=''}
function capture(){return{generation,epoch:identityEpoch(),project:projectId.value,type:props.typeId,actor:session.user?.accountId}}
function current(s:ReturnType<typeof capture>){return alive&&readable.value&&s.generation===generation&&s.epoch===identityEpoch()&&s.project===projectId.value&&s.type===props.typeId&&s.actor===session.user?.accountId}
async function load(review=false){if(!readable.value||busy.value||unknown.value&&!review)return;const s=capture();busy.value=true;error.value='';controller=new AbortController();try{const actual=await props.transport.read(s.project,s.type,controller.signal);if(!current(s))return;if(review)observed.value=actual;else value.value=actual}catch(cause){if(current(s)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&([401,403].includes(cause.status)||!review&&cause.status===404)){clear();denied.value=true}else error.value=errorMessage(cause)}}finally{if(current(s))busy.value=false}}
async function loadChoices(){if(!shown.value||!writable.value||mode.value!=='REPORTED'||choicesBusy.value)return;const s=capture(),choice=++choiceGeneration;controller=new AbortController();choicesBusy.value=true;error.value='';try{const actual=await props.transport.choices(s.project,s.type,props.typeStatus,controller.signal);if(current(s)&&choice===choiceGeneration&&shown.value&&mode.value==='REPORTED')choices.value=actual}catch(cause){if(current(s)&&choice===choiceGeneration&&shown.value&&!(cause instanceof IdentityChanged)){choices.value=[];error.value=errorMessage(cause)}}finally{if(current(s)&&choice===choiceGeneration)choicesBusy.value=false}}
function open(){if(!writable.value||props.disabled||busy.value||unknown.value||!value.value)return;mode.value=value.value.mode;propertyKey.value=value.value.propertyKey||'';choices.value=[];shown.value=true;error.value='';notice.value='';if(mode.value==='REPORTED')void loadChoices()}
function cancel(){if(!busy.value){choiceGeneration++;controller?.abort();choicesBusy.value=false;shown.value=false}}
async function save(){
 if(!shown.value||!writable.value||props.disabled||busy.value||unknown.value||choicesBusy.value||!value.value)return
 let chosen:IccidPolicyIntent;try{if(mode.value==='REPORTED'&&!choices.value.includes(propertyKey.value))throw new Error('请选择当前可报告TEXT属性');chosen=prepareIccidPolicy(projectId.value,props.typeId,value.value,mode.value,mode.value==='REPORTED'?propertyKey.value:undefined)}catch(cause){error.value=errorMessage(cause);return}
 const same=value.value.mode===chosen.body.mode&&value.value.propertyKey===chosen.body.propertyKey;intent.value=chosen;observed.value=undefined;unknown.value=true;shown.value=false;busy.value=true;error.value='';const s=capture();controller=new AbortController();let accepted=false
 try{const returned=await props.transport.change(chosen,controller.signal);accepted=true;if(!current(s))return;if(returned.deviceTypeId!==chosen.typeId||returned.mode!==chosen.body.mode||returned.propertyKey!==chosen.body.propertyKey||returned.revision!==String(BigInt(chosen.body.revision)+(same?0n:1n)))throw new Error('ICCID来源保存回执不符');const actual=await props.transport.read(chosen.project,chosen.typeId,controller.signal);if(!current(s))return;if(actual.mode!==returned.mode||actual.propertyKey!==returned.propertyKey||actual.revision!==returned.revision)throw new Error('当前来源已变化');value.value=actual;unknown.value=false;intent.value=undefined;notice.value='ICCID资料来源已保存；未创建或验证运营商卡。';emit('changed')}
 catch(cause){if(current(s)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&(cause.status===401||accepted&&cause.status===403)){clear();denied.value=true;return}if(!accepted&&cause instanceof ApiError&&!cause.outcomeUnknown&&[400,403,404,409,413,422,429].includes(cause.status)&&cause.code!==10014){unknown.value=false;intent.value=undefined;value.value=undefined;error.value='本次保存被拒绝，请读取当前策略后编辑。'}else error.value='原保存结果尚未核对；只读取，不会再次提交。'}}finally{if(current(s))busy.value=false}
}
function finish(){if(!unknown.value||busy.value||!observed.value)return;value.value=observed.value;unknown.value=false;intent.value=undefined;observed.value=undefined;error.value='';notice.value='已采用当前来源；原保存结果仍未确认，未重新提交。'}
function toggleCompact(next:unknown){if(typeof next!=='boolean'||!writable.value||props.disabled||locked.value||!value.value)return;mode.value=next?'MANUAL':'DISABLED';propertyKey.value='';shown.value=true;void save()}
function reset(){clear();denied.value=false;if(readable.value)void load()}
watch([()=>projectId.value,()=>props.typeId,()=>session.user?.accountId,()=>session.ready,()=>session.transitioning,()=>can('device:read'),()=>roles.includes(session.user?.projectRole||''),()=>roles.includes(currentProject.value?.myRole||'')],reset,{immediate:true,flush:'sync'});watch(writable,allowed=>{if(!allowed)cancel()},{flush:'sync'});watch(locked,v=>emit('locked',v),{immediate:true,flush:'sync'})
const dispose=onIdentityChange(reset);onScopeDispose(()=>{alive=false;clear();dispose();emit('locked',false)})
</script>
<template><div v-if="compact" class="extension-policy-control">
 <el-switch :model-value="!!value && value.mode !== 'DISABLED'" aria-label="启用物联卡ICCID" :loading="busy" :disabled="disabled||!writable||locked||!value" @change="toggleCompact"/>
 <el-button v-if="value && value.mode !== 'DISABLED' && writable" class="extension-policy-edit" size="small" :disabled="disabled||locked" @click="open">编辑</el-button><span v-if="!readable" role="status">无读取权限</span><span v-if="notice" role="status" class="tl-muted">{{notice}}</span>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <template v-if="unknown"><el-button size="small" :loading="busy" @click="load(true)">读取当前配置</el-button><el-button size="small" :disabled="busy||!observed" @click="finish">采用当前配置</el-button></template>
 <el-button v-else-if="error" size="small" :disabled="busy" @click="load()">重新读取</el-button>
 </div><section v-else class="iccid-policy"><header><h3>ICCID资料</h3><el-button v-if="writable" size="small" :disabled="disabled||locked||!value" @click="open">设置ICCID资料来源</el-button></header><p>保存未核验的设备标识，可人工维护或来自固定模型的TEXT上报。关闭仅隐藏有效标识，原人工资料保留；不提供运营商卡、流量或费用服务。</p><p v-if="!readable">当前账号没有读取权限。</p><template v-else><p v-if="value">当前来源：{{value.mode==='DISABLED'?'已关闭':value.mode==='MANUAL'?'人工未核验资料':'设备报告（'+value.propertyKey+'）'}} · 版本 {{value.revision}}</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="info" :closable="false"/><template v-if="unknown"><p>原请求键：{{intent?.key}}；当前同值不能证明原请求结果。</p><p v-if="observed">当前读取：{{observed.mode==='DISABLED'?'关闭':observed.mode==='MANUAL'?'人工未核验资料':'设备报告（'+observed.propertyKey+'）'}}，版本 {{observed.revision}}</p><el-button :loading="busy" @click="load(true)">读取当前ICCID来源核对</el-button><el-button :disabled="busy||!observed" @click="finish">采用当前来源并结束核对</el-button></template><el-button v-else size="small" :loading="busy" :disabled="busy||shown" @click="load()">刷新ICCID来源</el-button></template>
</section><el-dialog :model-value="shown&&readable&&writable" :title="compact?'编辑扩展信息':'ICCID资料来源'" width="min(580px,94vw)" :close-on-click-modal="false" @close="cancel"><el-form label-position="top"><el-form-item label="来源"><el-select v-model="mode" aria-label="ICCID资料来源" @change="loadChoices"><el-option label="关闭" value="DISABLED"/><el-option label="人工未核验资料" value="MANUAL"/><el-option label="设备TEXT报告" value="REPORTED"/></el-select></el-form-item><el-form-item v-if="mode==='REPORTED'" label="报告属性标识符"><el-select v-model="propertyKey" aria-label="ICCID报告属性" :loading="choicesBusy"><el-option v-for="key in choices" :key="key" :label="key" :value="key"/></el-select></el-form-item></el-form><p>1至32位数字为本平台技术预算，保留前导零，不自动删空格、转换填充字符或验证真实卡。报告缺失或模型不合格不会回退人工资料。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="cancel">取消</el-button><el-button type="primary" :disabled="disabled||!writable||busy||choicesBusy" @click="save">保存ICCID来源</el-button></template></el-dialog></template>
<style scoped>.iccid-policy header{display:flex;align-items:center;justify-content:space-between;gap:12px}.iccid-policy p{font-size:13px;line-height:1.7;overflow-wrap:anywhere}</style>
